function loadJson(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function parseMoney(value){const n=Number(String(value??'').trim().replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)&&n>=0?Math.round(n*100)/100:null}
function loadPrefs(){const stored=loadJson(HUB_PREFS_KEY,{}),calc=loadJson(CALC_STORAGE_KEY,{});return{theme:['dark','light'].includes(stored.theme)?stored.theme:(['dark','light'].includes(calc.theme)?calc.theme:'dark'),view:Object.hasOwn(VIEW_META,stored.view)?stored.view:'work',workFilter:['all',...STEPS.map(s=>s.id)].includes(stored.workFilter)?stored.workFilter:'all',workSort:['newest','oldest','progress'].includes(stored.workSort)?stored.workSort:'newest',soldTab:['app','historic'].includes(stored.soldTab)?stored.soldTab:'app',facebookEnabled:stored.facebookEnabled!==false,ebayShipping:Math.max(MIN_EBAY_SHIPPING,parseMoney(stored.ebayShipping??calc.ebayShipping)||MIN_EBAY_SHIPPING),lastSalePlatform:SELLING_PLATFORMS.includes(stored.lastSalePlatform)?stored.lastSalePlatform:'Vinted'}}
