function ensureMigration(){if(localStorage.getItem(GOOGLE_MIGRATION_KEY)===String(GOOGLE_MIGRATION.version))return;if(!inventory.length&&Array.isArray(GOOGLE_MIGRATION.inventory))inventory=normalizeInventory(GOOGLE_MIGRATION.inventory);if(!salesHistory.length&&Array.isArray(GOOGLE_MIGRATION.salesHistory))salesHistory=normalizeSalesHistory(GOOGLE_MIGRATION.salesHistory);saveInventory();saveSalesHistory();localStorage.setItem(GOOGLE_MIGRATION_KEY,String(GOOGLE_MIGRATION.version))}
function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function money(v){return fmt.money.format(Number(v)||0)}function num(v){return fmt.input.format(Number(v)||0)}function date(v){if(!v)return'—';const d=new Date(`${v}T12:00:00`);return Number.isNaN(d.getTime())?v:fmt.date.format(d)}
function price(key,v){return key==='grailed'?`${fmt.whole.format(v)} $`:['subito','facebook','vestiaire'].includes(key)?`${fmt.whole.format(v)} €`:`${fmt.x90.format(v)} €`}
function selected(){return inventory.find(i=>i.id===selectedItemId)||null}
function toast(message){clearTimeout(toastTimer);el.toast.textContent=message;el.toast.classList.add('visible');toastTimer=setTimeout(()=>el.toast.classList.remove('visible'),1900)}
async function copy(text,message='Copiato'){if(!text)return false;try{await navigator.clipboard.writeText(String(text))}catch{const a=document.createElement('textarea');a.value=String(text);a.setAttribute('readonly','');a.style.position='fixed';a.style.left='-9999px';a.style.opacity='0';document.body.append(a);a.select();document.execCommand('copy');a.remove()}toast(message);return true}
function showCopied(button,label='✓ Copiato'){if(!button)return;const original=button.dataset.originalLabel||button.textContent;button.dataset.originalLabel=original;button.textContent=label;button.classList.add('copied');button.disabled=true;setTimeout(()=>{if(!button.isConnected)return;button.textContent=button.dataset.originalLabel||original;button.classList.remove('copied');button.disabled=false},1350)}
