function openDialog(d){if(!d?.open)d?.showModal();document.body.classList.add('dialog-open')}function closeDialog(d){if(d?.open)d.close();if(![...document.querySelectorAll('dialog')].some(x=>x.open))document.body.classList.remove('dialog-open')}
function download(name,content,type='text/plain'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
function launch(url,target='_self'){if(!url)return;const a=document.createElement('a');a.href=url;a.target=target;a.rel='noopener noreferrer';a.style.display='none';document.body.append(a);a.click();a.remove()}
function launchPlatform(p){if(!p)return;if(p.launchMode==='safari'&&p.safariUrl)return launch(p.safariUrl);if(p.launchMode==='universal'&&p.universalUrl)return launch(p.universalUrl);if(!p.appUrl)return launch(p.webUrl,'_blank');let t=setTimeout(()=>{if(document.visibilityState!=='hidden')launch(p.webUrl,'_blank')},1000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')clearTimeout(t)},{once:true});launch(p.appUrl)}
function formatBytes(value){const bytes=Math.max(0,Number(value)||0);if(bytes<1024)return`${bytes} B`;if(bytes<1024**2)return`${(bytes/1024).toFixed(1).replace('.',',')} KB`;return`${(bytes/1024**2).toFixed(1).replace('.',',')} MB`}
function formatDuration(value){const seconds=Math.max(0,Math.round(Number(value)||0));if(!seconds)return'';const minutes=Math.floor(seconds/60),rest=String(seconds%60).padStart(2,'0');return`${minutes}:${rest}`}
function clearResearchVideoPreview(){if(researchVideoUrl){URL.revokeObjectURL(researchVideoUrl);researchVideoUrl=''}el.vintedVideoPreview.innerHTML='';el.vintedVideoPreview.hidden=true}
function videoDuration(file){return new Promise(resolve=>{const video=document.createElement('video'),url=URL.createObjectURL(file);video.preload='metadata';video.onloadedmetadata=()=>{const duration=Number.isFinite(video.duration)?video.duration:0;URL.revokeObjectURL(url);resolve(duration)};video.onerror=()=>{URL.revokeObjectURL(url);resolve(0)};video.src=url})}
async function selectResearchVideo(file){const item=selected();if(!item||!file)return;if(!String(file.type||'').startsWith('video/'))return toast('Seleziona un file video');if(file.size>500*1024*1024)return toast('Il video supera 500 MB: accorcialo prima');const duration=await videoDuration(file);activeResearchVideo=file;activeResearchVideoItemId=item.id;const current=normalizeListing(item.listing);item.listing={...current,vintedVideoReady:true,vintedVideoName:file.name||'Video comparabili',vintedVideoSize:file.size||0,vintedVideoDuration:duration,vintedVideoSelectedAt:new Date().toISOString(),vintedAnalysis:{},vintedSuggestedTarget:0,vintedResearchUpdatedAt:new Date().toISOString()};saveInventory();renderResearch(item);renderWork();toast('Video comparabili selezionato')}
function titles(item){const l=normalizeListing(item.listing),g=Array.isArray(l.generatedTitles)?l.generatedTitles:[];return g.length===3&&g.every(Boolean)?g:generateTitleVariants(item)}
function checks(item){const l=normalizeListing(item.listing),plan=getPublishPlan(item,prefs);return[l.photoCount>0&&Boolean(item.brand||item.title)&&Boolean(item.category),l.generatedTitles.length===3&&l.generatedTitles.every(Boolean)&&Boolean(l.baseDescription.trim()),Number(item.target)>0,Boolean(l.pricesConfirmed),plan.length>0&&plan.every(p=>getPlatformState(item,p.id)==='live')]}
function nextStep(item){if(item.status==='live')return 4;const i=checks(item).findIndex(done=>!done);return i<0?4:i}function stage(item){return STEPS[nextStep(item)]}function progress(item){return checks(item).filter(Boolean).length*20}function plan(item){return getPublishPlan(item,prefs)}function calc(item){return item?.target>0?calculateMXLABPrices(item.target,prefs.ebayShipping):null}
