function navigate(view){if(!Object.hasOwn(VIEW_META,view))return;prefs.view=view;savePrefs();document.querySelectorAll('.view').forEach(s=>{const a=s.dataset.view===view;s.hidden=!a;s.classList.toggle('active',a)});document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));[el.pageTitle.textContent,el.pageSubtitle.textContent]=VIEW_META[view];document.getElementById('quickAddButton').hidden=view!=='work';renderCurrent();scrollTo(0,0)}
