async function hydrate(container){await Promise.all([...container.querySelectorAll('[data-cover]')].map(async node=>{const photos=await getItemPhotos(node.dataset.cover).catch(()=>[]);if(!photos[0])return;const url=URL.createObjectURL(photos[0].blob);cardUrls.push(url);node.innerHTML=`<img src="${url}" alt="Copertina">`}))}
function card(item){const s=nextStep(item),l=normalizeListing(item.listing),drafts=plan(item).filter(p=>getPlatformState(item,p.id)==='draft').length;return`<article class="item-card"><div class="cover" data-cover="${item.id}">▧</div><div class="item-main"><div class="item-top"><div><span class="code">${esc(item.code)}</span><h3>${esc([item.brand,item.title].filter(Boolean).join(' · ')||item.category||'Articolo')}</h3></div><span class="stage">${s+1}/5 · ${esc(stage(item).label)}</span></div><div class="meta"><span>${esc(item.category||'Tipologia da inserire')}</span>${item.size?`<span>Taglia ${esc(item.size)}</span>`:''}${item.target?`<span>Target ${money(item.target)}</span>`:''}${drafts?`<span>${drafts} bozze</span>`:''}</div><div class="progress"><b style="width:${progress(item)}%"></b></div><div class="next"><p>${esc(stage(item).action)}</p><button data-open="${item.id}" data-step="${s}">Continua →</button></div></div></article>`}
function renderWork(){revokeCards();const all=inventory.filter(i=>!['live','sold'].includes(i.status));el.workCount.textContent=all.length;el.draftCount.textContent=all.filter(i=>plan(i).some(p=>getPlatformState(i,p.id)==='draft')).length;el.publishCount.textContent=all.filter(i=>nextStep(i)===4).length;let rows=all.filter(i=>match(i,el.workSearch.value));if(prefs.workFilter!=='all')rows=rows.filter(i=>stage(i).id===prefs.workFilter);rows.sort((a,b)=>prefs.workSort==='oldest'?String(a.createdAt).localeCompare(String(b.createdAt)):prefs.workSort==='progress'?nextStep(b)-nextStep(a):String(b.createdAt).localeCompare(String(a.createdAt)));el.workResultCount.textContent=`${rows.length} ${rows.length===1?'articolo':'articoli'}`;el.workEmpty.hidden=all.length>0;el.workList.hidden=rows.length===0;el.workList.innerHTML=rows.map(card).join('');hydrate(el.workList);el.workList.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openWorkflow(b.dataset.open,Number(b.dataset.step)))}
function liveCard(item){const online=plan(item).filter(p=>getPlatformState(item,p.id)==='live'),published=normalizeListing(item.listing).publishedAt?.slice(0,10)||item.updatedAt?.slice(0,10),name=[item.brand,item.title].filter(Boolean).join(' · ')||item.category||'Articolo';return`<article class="published-card"><div class="cover published-cover" data-cover="${item.id}">▧</div><div class="published-main"><div class="published-top"><span class="code">${esc(item.code)}</span><time>${date(published)}</time></div><h3>${esc(name)}</h3><div class="published-facts"><span><b>${online.length}</b> piattaforme</span><span><b>${money(item.target)}</b> target</span></div></div><div class="published-actions"><button data-open="${item.id}">Gestisci annunci</button><button class="primary-mini" data-sell="${item.id}">Segna venduto</button></div></article>`}
function renderLive(){revokeCards();const all=inventory.filter(i=>i.status==='live'),rows=all.filter(i=>match(i,el.liveSearch.value)).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));el.liveCount.textContent=all.length;el.liveTarget.textContent=money(all.reduce((s,i)=>s+i.target,0));el.livePlatforms.textContent=all.reduce((s,i)=>s+plan(i).filter(p=>getPlatformState(i,p.id)==='live').length,0);el.liveResultCount.textContent=`${rows.length} ${rows.length===1?'articolo':'articoli'}`;el.liveEmpty.hidden=all.length>0;el.liveList.hidden=rows.length===0;el.liveList.innerHTML=rows.map(liveCard).join('');hydrate(el.liveList);el.liveList.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openWorkflow(b.dataset.open,4));el.liveList.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>openSale(b.dataset.sell))}
function soldCard(item){const profit=getItemProfit(item)||0,mult=getItemMultiplier(item);return`<article class="item-card"><div class="cover" data-cover="${item.id}">▧</div><div class="item-main"><div class="item-top"><div><span class="code">${esc(item.code)}</span><h3>${esc([item.brand,item.title].filter(Boolean).join(' · '))}</h3></div><span class="stage done">Venduto</span></div><div class="meta"><span>${esc(item.sale.platform)}</span><span>${date(item.sale.date)}</span><span>Vendita ${money(item.sale.price)}</span><span>Profitto ${money(profit)}</span>${mult?`<span>${num(mult)}×</span>`:''}</div><div class="card-buttons"><button data-copy-sale="${item.id}">Copia dati vendita</button><button data-remove="${item.id}">Rimuovi annunci</button></div></div></article>`}
function historicCard(s){const p=s.currency==='USD'?`${fmt.whole.format(s.price)} $`:money(s.price);return`<article class="item-card"><div class="cover">✓</div><div class="item-main"><div class="item-top"><div><span class="code">${esc(s.platform)}</span><h3>${esc(s.title)}</h3></div><span class="stage done">${p}</span></div><div class="meta"><span>${date(s.date)}</span>${s.country?`<span>${esc(s.country)}</span>`:''}</div></div></article>`}
function renderSold(){revokeCards();const sold=inventory.filter(i=>i.status==='sold'&&i.sale);el.soldCount.textContent=sold.length;el.soldNet.textContent=money(sold.reduce((s,i)=>s+i.sale.net,0));el.soldProfit.textContent=money(sold.reduce((s,i)=>s+(getItemProfit(i)||0),0));document.querySelectorAll('[data-sold-tab]').forEach(b=>b.classList.toggle('active',b.dataset.soldTab===prefs.soldTab));if(prefs.soldTab==='app'){const rows=sold.filter(i=>match(i,el.soldSearch.value)).sort((a,b)=>String(b.sale.date).localeCompare(String(a.sale.date)));el.soldEmpty.hidden=sold.length>0;el.soldList.hidden=rows.length===0;el.soldList.innerHTML=rows.map(soldCard).join('');hydrate(el.soldList);el.soldList.querySelectorAll('[data-copy-sale]').forEach(b=>b.onclick=()=>copySale(inventory.find(i=>i.id===b.dataset.copySale)));el.soldList.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>openRemoval(inventory.find(i=>i.id===b.dataset.remove)))}else{const q=el.soldSearch.value.toLowerCase(),rows=salesHistory.filter(s=>[s.title,s.platform,s.country].join(' ').toLowerCase().includes(q)).sort((a,b)=>String(b.date).localeCompare(String(a.date)));el.soldEmpty.hidden=salesHistory.length>0;el.soldList.hidden=rows.length===0;el.soldList.innerHTML=rows.map(historicCard).join('')}}
