function renderPhotos(){revokePhotos();el.workflowPhotoCount.textContent=`${activePhotos.length} / 12`;if(!activePhotos.length){el.workflowPhotoGrid.innerHTML='<div class="photo-empty"><div><strong>Nessuna foto</strong><br><small>Seleziona le immagini definitive.</small></div></div>';return}el.workflowPhotoGrid.innerHTML=activePhotos.map((p,i)=>{const u=URL.createObjectURL(p.blob);photoUrls.push(u);return`<article class="photo" data-photo="${p.id}"><button class="set-cover"></button><img src="${u}" alt="Foto ${i+1}">${i===0?'<span class="cover-label">Copertina</span>':''}<button class="delete">×</button></article>`}).join('');el.workflowPhotoGrid.querySelectorAll('.set-cover').forEach(b=>b.onclick=async()=>{await setCoverPhoto(selectedItemId,b.closest('[data-photo]').dataset.photo);activePhotos=await getItemPhotos(selectedItemId);renderPhotos()});el.workflowPhotoGrid.querySelectorAll('.delete').forEach(b=>b.onclick=async e=>{e.stopPropagation();await deletePhoto(b.closest('[data-photo]').dataset.photo);activePhotos=await getItemPhotos(selectedItemId);const item=selected();item.listing={...normalizeListing(item.listing),photoCount:activePhotos.length};saveInventory();renderPhotos();renderWork()})}
