function collectData(item){item.brand=document.getElementById('wfBrand').value.trim();item.category=document.getElementById('wfCategory').value.trim()||'Altro';item.title=document.getElementById('wfTitle').value.trim();item.size=document.getElementById('wfSize').value.trim();item.condition=document.getElementById('wfCondition').value;item.cost=parseMoney(document.getElementById('wfCost').value)||0;item.purchaseDate=document.getElementById('wfPurchaseDate').value||localDateISO();item.source=document.getElementById('wfSource').value.trim();item.listing={...normalizeListing(item.listing),aiNotes:document.getElementById('wfAiNotes').value.trim(),photoCount:activePhotos.length,updatedAt:new Date().toISOString()};item.updatedAt=new Date().toISOString()}
function renderTitles(item){const arr=titles(item),labels=['Vinted · max 100','Wallapop / Subito · max 50','eBay · max 80'],limits=[100,50,80];el.titleInputs.innerHTML=arr.map((t,i)=>`<article class="title-box"><header><span>${labels[i]}</span><button data-copy-title="${i}">Copia</button></header><textarea data-title="${i}" maxlength="${limits[i]}">${esc(t)}</textarea><footer><span>Stesse keyword principali</span><em>${t.length} / ${limits[i]}</em></footer></article>`).join('');el.titleInputs.querySelectorAll('[data-title]').forEach(x=>x.oninput=()=>{x.closest('.title-box').querySelector('em').textContent=`${x.value.length} / ${limits[Number(x.dataset.title)]}`});el.titleInputs.querySelectorAll('[data-copy-title]').forEach(b=>b.onclick=()=>copyFromButton(b,el.titleInputs.querySelector(`[data-title="${b.dataset.copyTitle}"]`).value,'Titolo copiato'))}
function collectListing(item){const current=normalizeListing(item.listing),arr=[...el.titleInputs.querySelectorAll('[data-title]')].map(x=>x.value.trim());item.listing={...current,generatedTitles:arr.length===3&&arr.every(Boolean)?arr:current.generatedTitles,baseDescription:el.wfDescription.value.trim()||current.baseDescription,vestiaireEnabled:el.wfVestiaire.checked,photoCount:activePhotos.length,updatedAt:new Date().toISOString()};item.updatedAt=new Date().toISOString()}
function renderAnalysisResult(item){const a=normalizeListing(item.listing).vintedAnalysis;if(!a.status){el.vintedAnalysisResult.hidden=true;el.vintedAnalysisResult.innerHTML='';return}el.vintedAnalysisResult.hidden=false;if(a.status==='insufficient'){el.vintedAnalysisResult.innerHTML=`<article class="wide"><span>Analisi non sufficiente · Affidabilità ${esc(a.confidence||'Bassa')}</span><strong>Registra più risultati leggibili</strong><small>${esc(a.reason)}</small></article>`;return}const range=a.rangeMin||a.rangeMax?`${num(a.rangeMin)}–${num(a.rangeMax)} €`:'—';el.vintedAnalysisResult.innerHTML=`<article class="analysis-target"><span>Target proposto</span><strong>${money(a.target)}</strong></article><article><span>Affidabilità</span><strong>${esc(a.confidence||'—')}</strong></article><article><span>Più frequente</span><strong>${a.mode?money(a.mode):'—'}</strong></article><article><span>Ponderato</span><strong>${a.weighted?money(a.weighted):'—'}</strong></article><article><span>Fascia centrale</span><strong>${range}</strong></article><article><span>Campione valido</span><strong>${a.validCount} / ${a.readCount}</strong></article><article class="wide"><span>Motivo</span><small>${esc(a.reason)}</small></article>`}
function renderResearch(item){const l=normalizeListing(item.listing),file=activeResearchVideoItemId===item.id?activeResearchVideo:null;el.vintedTarget.value=l.vintedAnalysis.target?num(l.vintedAnalysis.target):item.target?num(item.target):'';clearResearchVideoPreview();if(file){el.vintedVideoTitle.textContent=file.name||'Video comparabili';el.vintedVideoMeta.textContent=[formatDuration(l.vintedVideoDuration),formatBytes(file.size)].filter(Boolean).join(' · ');researchVideoUrl=URL.createObjectURL(file);el.vintedVideoPreview.innerHTML=`<video src="${researchVideoUrl}" controls muted playsinline preload="metadata"></video>`;el.vintedVideoPreview.hidden=false}else if(l.vintedVideoName){el.vintedVideoTitle.textContent=`Ultimo video: ${l.vintedVideoName}`;el.vintedVideoMeta.textContent=`${[formatDuration(l.vintedVideoDuration),formatBytes(l.vintedVideoSize)].filter(Boolean).join(' · ')||'Video registrato'} · riselezionalo solo per rianalizzarlo`}else{el.vintedVideoTitle.textContent='Seleziona video comparabili';el.vintedVideoMeta.textContent='Foto o File · consigliati 30–90 secondi'}const ready=priceAiConfigured();el.priceAiStatusBadge.textContent=ready?'Configurato':'Da configurare';el.priceAiStatusBadge.classList.toggle('ready',ready);el.priceAiStatusText.textContent=l.vintedAnalysis.status==='ok'?'Risultato importato: controlla il target e salvalo.':l.vintedAnalysis.status==='insufficient'?'Il risultato precedente non è sufficiente: riprova con i fotogrammi estratti.':file?`Video pronto. L’app estrarrà fino a 18 fotogrammi leggibili per “${MXLAB_PRICE_SHORTCUT_NAME}”.`:'Il video non viene salvato dentro l’app: resta nella galleria o in File.';renderAnalysisResult(item)}
function renderPrices(item){if(!item.target){el.priceTargetBanner.innerHTML='<span>Prezzo target</span><strong>Da inserire</strong>';el.workflowPriceList.innerHTML='<p class="hint">Completa prima la ricerca prezzo.</p>';return}const m=calc(item),rows=[['vinted','Vinted'],['wallapop','Wallapop'],['ebay','eBay'],['subito','Subito'],['facebook','Facebook'],['vestiaire','Vestiaire'],['depopBoost','Depop · con boost'],['grailed','Grailed']];el.priceTargetBanner.innerHTML=`<span>Prezzo target</span><strong>${money(item.target)}</strong>`;el.workflowPriceList.innerHTML=rows.map(([k,l])=>`<article class="price-row"><div><h4>${l}</h4><small>Minimo ${price(k,m.minimums[k])}${m.offers[k]!=null?` · Offerta ${price(k,m.offers[k])}`:''}</small></div><strong>${price(k,m.prices[k])}</strong></article>`).join('')}
function platformMarkup(item,p,c){const st=getPlatformState(item,p.id),label=p.id==='depop'?'Depop · con boost':p.label;return`<article class="platform-card" data-platform="${p.id}"><div class="platform-head"><span class="platform-badge">${esc(p.badge)}</span><div><h4>${esc(label)}</h4><small>${st==='live'?'Online':st==='draft'?'Bozza pronta':'Da preparare'}</small></div><strong>${price(p.id,c.price)}</strong></div><div class="platform-tools"><button data-action="title">Copia titolo</button><button data-action="description">Copia descrizione</button><button data-action="open" class="open-platform">Apri</button></div><div class="platform-state"><button data-state="todo" class="${st==='todo'?'active':''}">Da fare</button><button data-state="draft" class="${st==='draft'?'active':''}">Bozza</button><button data-state="live" class="${st==='live'?'active':''}">Online</button></div></article>`}
function renderPlatforms(item){if(!item.target){el.platformCards.innerHTML='<p class="hint">Definisci prima il target.</p>';el.completePublishingButton.disabled=true;return}const m=calc(item),contents=generatePlatformContent(item,m),ps=plan(item),live=ps.filter(p=>getPlatformState(item,p.id)==='live').length;el.platformProgress.textContent=`${live} / ${ps.length}`;el.platformCards.innerHTML=ps.map(p=>platformMarkup(item,p,contents[p.id])).join('');el.completePublishingButton.disabled=!ps.length||live<ps.length;el.publishingHint.textContent=live===ps.length?'Tutte le piattaforme sono online. Puoi completare.':`Mancano ${ps.length-live} piattaforme da segnare Online.`;el.platformCards.querySelectorAll('[data-platform]').forEach(card=>{const p=getPlatform(card.dataset.platform),c=contents[p.id],label=p.id==='depop'?'Depop con boost':p.label;card.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{collectListing(item);saveInventory();if(b.dataset.action==='title')return copyFromButton(b,c.title,`Titolo ${label} copiato`);if(b.dataset.action==='description')return copyFromButton(b,c.description,`Descrizione ${label} copiata`);launchPlatform(p)});card.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{item.listing=setPlatformState(item,p.id,b.dataset.state);saveInventory();renderPlatforms(item);renderWork()})})}
function renderStepper(item){const done=checks(item);el.workflowStepper.querySelectorAll('[data-step]').forEach(b=>{const s=Number(b.dataset.step);b.classList.toggle('active',s===activeStep);b.classList.toggle('done',done[s])});document.querySelectorAll('[data-workflow-step]').forEach(s=>s.hidden=Number(s.dataset.workflowStep)!==activeStep);el.workflowBackButton.disabled=activeStep===0;el.workflowNextButton.hidden=activeStep===4;el.workflowNextButton.textContent=activeStep===3?'Conferma prezzi e continua':'Salva e continua'}
function renderStep(item){renderStepper(item);if(activeStep===0)renderPhotos();if(activeStep===1){renderTitles(item);el.wfDescription.value=normalizeListing(item.listing).baseDescription||''}if(activeStep===2)renderResearch(item);if(activeStep===3)renderPrices(item);if(activeStep===4)renderPlatforms(item)}
async function openWorkflow(id,step=null){const item=inventory.find(i=>i.id===id);if(!item||item.status==='sold')return;clearResearchVideoPreview();activeResearchVideo=null;activeResearchVideoItemId=null;selectedItemId=item.id;item.listing=normalizeListing(item.listing);activePhotos=await getItemPhotos(id).catch(()=>[]);item.listing.photoCount=activePhotos.length;fillData(item);renderTitles(item);el.wfDescription.value=item.listing.baseDescription||'';el.workflowCode.textContent=item.code;el.workflowTitle.textContent=[item.brand,item.title].filter(Boolean).join(' · ')||item.category||'Lavorazione';el.wfVestiaire.checked=item.listing.vestiaireEnabled;activeStep=step==null?nextStep(item):Math.max(0,Math.min(4,step));updateAi();updatePriceAi();renderStep(item);openDialog(el.workflowDialog);saveInventory()}
function saveStep(){const item=selected();if(!item)return;collectData(item);if(activeStep>=1)collectListing(item);if(activeStep===3&&item.target>0)item.listing={...normalizeListing(item.listing),pricesConfirmed:true};updateStatus(item);saveInventory();renderWork();renderLive()}
function configured(){return localStorage.getItem(AI_SHORTCUT_CONFIG_KEY)==='1'}function updateAi(msg=''){el.aiStatusBadge.textContent=configured()?'Configurato':'Da configurare';el.aiStatusBadge.classList.toggle('ready',configured());if(msg)el.aiStatusText.textContent=msg}function openAiSetup(){el.aiShortcutPrompt.value=`${MXLAB_SHORTCUT_PROMPT}\n\nInserisci inoltre le variabili “Input rapido” e “Appunti”.`;el.aiConfiguredCheck.checked=configured();openDialog(el.aiSetupDialog)}function priceAiConfigured(){return localStorage.getItem(PRICE_AI_SHORTCUT_CONFIG_KEY)==='1'}function updatePriceAi(msg=''){if(!el.priceAiStatusBadge)return;el.priceAiStatusBadge.textContent=priceAiConfigured()?'Configurato':'Da configurare';el.priceAiStatusBadge.classList.toggle('ready',priceAiConfigured());if(msg)el.priceAiStatusText.textContent=msg}function openPriceAiSetup(){el.priceAiShortcutPrompt.value=`${MXLAB_PRICE_SHORTCUT_PROMPT}\n\nIMMAGINI: [Input rapido]\n\nISTRUZIONI COMPLETE: [Appunti]`;el.priceAiConfiguredCheck.checked=priceAiConfigured();openDialog(el.priceAiSetupDialog)}
async function generateAI(){const item=selected();if(!item)return;collectData(item);if(!activePhotos.length)return toast('Importa prima almeno una foto');if(!configured())return openAiSetup();const brief=buildMXLABAIInput(item,item.listing.aiNotes,activePhotos.length);await copy(brief,'Istruzioni MXLAB preparate');const files=activePhotos.map(photoToFile);if(!navigator.share||!navigator.canShare?.({files}))return toast('Condivisione foto non disponibile');try{updateAi(`Seleziona “${MXLAB_SHORTCUT_NAME}”.`);await navigator.share({title:`${item.code} · MXLAB Annuncio`,text:'Le istruzioni complete sono negli appunti.',files});updateAi('Quando termina, premi Importa risultato.')}catch(e){if(e?.name!=='AbortError')toast('Impossibile avviare il comando')}}
async function importAI(){const item=selected();if(!item)return;try{const r=parseMXLABAIOutput(await readClipboard());item.listing={...normalizeListing(item.listing),generatedTitles:r.titles,baseDescription:r.description,aiGeneratedAt:new Date().toISOString(),aiSource:'Apple Intelligence · Comandi Rapidi',photoCount:activePhotos.length};saveInventory();renderTitles(item);el.wfDescription.value=r.description;updateAi(r.warnings.length?`Controlla: ${r.warnings.join(', ')}.`:'Annuncio importato correttamente.');renderWork();toast('Titoli e descrizione importati')}catch(e){toast(e.message||'Risultato non riconosciuto')}}
async function analyzeResearchVideo(){const item=selected();if(!item)return;collectData(item);collectListing(item);if(!activeResearchVideo||activeResearchVideoItemId!==item.id)return toast('Seleziona prima il video comparabili');if(!priceAiConfigured())return openPriceAiSetup();const brief=buildMXLABPriceAIInput(item);await copy(brief,'Istruzioni MXLAB Prezzo preparate');try{updatePriceAi('Estrazione fotogrammi 0%…');const extracted=await extractVideoFrames(activeResearchVideo,{minFrames:8,maxFrames:18,secondsPerFrame:4,maxWidth:720,quality:.84,onProgress:({current,total})=>updatePriceAi(`Estrazione fotogrammi ${Math.round(current/total*100)}%…`)});const files=extracted.files;if(!files.length)throw new Error('Nessun fotogramma estratto');if(!navigator.share||!navigator.canShare?.({files}))throw new Error('Condivisione immagini non disponibile');item.listing={...normalizeListing(item.listing),vintedResearchStarted:true,vintedResearchUpdatedAt:new Date().toISOString()};saveInventory();updatePriceAi(`Seleziona “${MXLAB_PRICE_SHORTCUT_NAME}” · ${files.length} immagini.`);await navigator.share({files});updatePriceAi('Quando termina, torna qui e premi Importa risultato.')}catch(e){if(e?.name!=='AbortError'){updatePriceAi('Impossibile preparare i fotogrammi.');toast(e?.message||'Impossibile avviare l’analisi')}}}
async function importPriceAnalysis(){const item=selected();if(!item)return;try{const result=parseMXLABPriceAIOutput(await readClipboard('Incolla qui il risultato di MXLAB Prezzo:'));item.listing={...normalizeListing(item.listing),vintedAnalysis:{...result,analyzedAt:new Date().toISOString()},vintedSuggestedTarget:result.target,vintedResearchStarted:true,vintedResearchUpdatedAt:new Date().toISOString()};if(result.status==='ok'&&result.target)el.vintedTarget.value=num(result.target);saveInventory();renderResearch(item);renderWork();toast(result.status==='ok'?'Analisi importata':'Video insufficiente: registra più risultati')}catch(e){toast(e.message||'Risultato prezzo non riconosciuto')}}
async function copyResearchPrompt(){const item=selected();if(!item)return;collectData(item);collectListing(item);saveInventory();await copy(buildMXLABPriceAIInput(item),'Prompt analisi video copiato')}
async function openChatGPTForResearch(){await copyResearchPrompt();launch('https://chatgpt.com/','_blank')}
function saveTarget(){const item=selected(),target=parseMoney(el.vintedTarget.value);if(!item||!target)return toast('Inserisci un target valido');collectData(item);collectListing(item);item.target=target;item.targetHistory=[...(item.targetHistory||[]),{target,date:localDateISO(),kind:item.targetHistory?.length?'change':'initial'}];item.targetSource='Video comparabili Vinted · analisi ChatGPT';item.listing={...normalizeListing(item.listing),vintedSuggestedTarget:target,pricesConfirmed:false,vintedResearchUpdatedAt:new Date().toISOString()};updateStatus(item);saveInventory();renderWork();toast('Prezzo target salvato');activeStep=3;renderStep(item);el.workflowBody.scrollTop=0}
function completePublishing(){const item=selected();if(!item)return;collectData(item);collectListing(item);const ps=plan(item);if(!ps.length||!ps.every(p=>getPlatformState(item,p.id)==='live'))return toast('Segna prima tutte le piattaforme come Online');item.status='live';item.platforms=ps.map(p=>p.label);item.listing={...normalizeListing(item.listing),pricesConfirmed:true,publishedAt:new Date().toISOString()};item.updatedAt=new Date().toISOString();saveInventory();closeDialog(el.workflowDialog);navigate('live');toast('Articolo spostato in Pubblicati')}
function validateNext(){const item=selected();if(!item)return;collectData(item);if(activeStep>=1)collectListing(item);if(activeStep===0&&(!activePhotos.length||(!item.brand&&!item.title)||!item.category))return toast('Completa foto, marca o nome e tipologia');if(activeStep===1){const l=normalizeListing(item.listing);if(l.generatedTitles.length!==3||!l.generatedTitles.every(Boolean)||!l.baseDescription)return toast('Completa i tre titoli e la descrizione')}if(activeStep===2&&!item.target)return toast('Salva prima il prezzo target');if(activeStep===3)item.listing={...normalizeListing(item.listing),pricesConfirmed:true};updateStatus(item);saveInventory();renderWork();if(activeStep<4){activeStep++;renderStep(item);el.workflowBody.scrollTop=0}}
function openSale(id){const item=inventory.find(i=>i.id===id);if(!item)return;selectedItemId=id;el.saleTitle.textContent=`Vendi ${item.code}`;el.salePlatform.innerHTML=SELLING_PLATFORMS.map(p=>`<option ${p===prefs.lastSalePlatform?'selected':''}>${esc(p)}</option>`).join('');el.salePrice.value=item.target?num(item.target):'';el.saleNet.value=item.target?num(item.target):'';el.saleCost.value=item.cost?num(item.cost):'';el.saleDate.value=localDateISO();salePreview();openDialog(el.saleDialog)}function salePreview(){const item=selected(),net=parseMoney(el.saleNet.value)||0,cost=parseMoney(el.saleCost.value)??item?.cost??0,profit=net-cost;el.saleProfitPreview.textContent=money(profit);el.saleMultiplierPreview.textContent=cost>0?`${num(net/cost)}×`:'—'}
function copySale(item){if(!item?.sale)return;const row=[item.sale.date,item.sale.platform,item.code,item.brand,item.title,item.category,item.size,num(item.cost),num(item.sale.price),num(item.sale.net),num(getItemProfit(item)||0)].join('\t');copy(row,'Dati vendita copiati per Fogli Google')}
function openRemoval(item){if(!item)return;selectedItemId=item.id;renderRemoval(item);openDialog(el.removalDialog)}function renderRemoval(item){const l=normalizeListing(item.listing),rows=l.removalChecklist||[];el.removalChecklist.innerHTML=rows.length?rows.map(e=>{const p=getPlatform(e.platformId),url=l.listingUrls?.[e.platformId]||p?.webUrl||'#';return`<article class="removal-row" data-removal="${e.platformId}"><label><input type="checkbox" ${e.done?'checked':''}><span><strong>${esc(p?.label||e.platformId)}</strong><small>${e.done?'Rimosso':'Da rimuovere'}</small></span></label><button data-url="${esc(url)}">Apri</button></article>`}).join(''):'<p class="hint">Nessun altro annuncio registrato.</p>';el.removalChecklist.querySelectorAll('[data-removal] input').forEach(x=>x.onchange=()=>{const e=item.listing.removalChecklist.find(r=>r.platformId===x.closest('[data-removal]').dataset.removal);if(e)e.done=x.checked;saveInventory();renderRemoval(item)});el.removalChecklist.querySelectorAll('[data-url]').forEach(b=>b.onclick=()=>launch(b.dataset.url,'_blank'))}
async function createItem(){const files=[...el.newItemPhotos.files];if(!files.length)return toast('Seleziona almeno una foto definitiva');const input={brand:document.getElementById('newBrand').value.trim(),category:document.getElementById('newCategory').value.trim()||'Altro',title:document.getElementById('newTitle').value.trim(),size:document.getElementById('newSize').value.trim(),condition:document.getElementById('newCondition').value,cost:parseMoney(document.getElementById('newCost').value)||0,purchaseDate:document.getElementById('newPurchaseDate').value||localDateISO(),source:document.getElementById('newSource').value.trim(),target:0,status:'prep',listing:{aiNotes:document.getElementById('newAiNotes').value.trim()}};const item=createInventoryItem(input,inventory);inventory.unshift(item);saveInventory();try{await addItemPhotos(item.id,files,0,12);activePhotos=await getItemPhotos(item.id);item.listing={...normalizeListing(item.listing),photoCount:activePhotos.length};item.status='photo';saveInventory()}catch{toast('Articolo creato, foto non importate')}closeDialog(el.newItemDialog);resetNew();renderWork();openWorkflow(item.id,0)}function resetNew(){el.newItemForm.reset();document.getElementById('newCondition').value='Ottime';document.getElementById('newPurchaseDate').value=localDateISO();el.newPhotoLabel.textContent='Nessuna foto selezionata'}
