function manual(){const t=parseMoney(el.manualTarget.value);if(!t){el.manualPriceList.innerHTML='<p class="hint">Inserisci un target valido.</p>';return}const m=calculateMXLABPrices(t,prefs.ebayShipping),rows=[['vinted','Vinted'],['wallapop','Wallapop'],['ebay','eBay'],['subito','Subito'],['facebook','Facebook'],['vestiaire','Vestiaire'],['depopBoost','Depop · con boost'],['grailed','Grailed']];el.manualPriceList.innerHTML=rows.map(([k,l])=>`<article class="price-row"><div><h4>${l}</h4><small>Minimo ${price(k,m.minimums[k])}</small></div><strong>${price(k,m.prices[k])}</strong></article>`).join('')}
function exportBackup(){download(`mxlab-backup-${localDateISO()}.json`,JSON.stringify({version:APP_VERSION,exportedAt:new Date().toISOString(),inventory,salesHistory,prefs},null,2),'application/json')}async function importBackup(file){try{const d=JSON.parse(await file.text());if(!Array.isArray(d.inventory))throw 0;inventory=normalizeInventory(d.inventory);salesHistory=normalizeSalesHistory(d.salesHistory||salesHistory);prefs={...prefs,...(d.prefs||{}),view:'work'};saveInventory();saveSalesHistory();savePrefs();applyTheme();navigate('work');toast('Backup importato')}catch{toast('Backup non valido')}}
function events(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));document.getElementById('brandButton').onclick=()=>navigate('work');document.getElementById('themeButton').onclick=()=>{prefs.theme=prefs.theme==='dark'?'light':'dark';savePrefs();applyTheme()};['quickAddButton','workAddButton','emptyAddButton'].forEach(id=>document.getElementById(id).onclick=()=>{resetNew();openDialog(el.newItemDialog)});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeDialog(document.getElementById(b.dataset.close)));el.newItemPhotos.onchange=()=>el.newPhotoLabel.textContent=el.newItemPhotos.files.length?`${el.newItemPhotos.files.length} foto selezionate`:'Nessuna foto selezionata';el.newItemForm.onsubmit=e=>{e.preventDefault();createItem()};el.workSearch.oninput=renderWork;el.workSort.onchange=()=>{prefs.workSort=el.workSort.value;savePrefs();renderWork()};el.workFilters.querySelectorAll('[data-work-filter]').forEach(b=>b.onclick=()=>{prefs.workFilter=b.dataset.workFilter;savePrefs();el.workFilters.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));renderWork()});el.liveSearch.oninput=renderLive;el.soldSearch.oninput=renderSold;el.soldTabs.querySelectorAll('[data-sold-tab]').forEach(b=>b.onclick=()=>{prefs.soldTab=b.dataset.soldTab;savePrefs();renderSold()});document.querySelectorAll('[data-message]').forEach(b=>b.onclick=()=>copy(BUYER_MESSAGES[b.dataset.message],'Messaggio copiato'));
el.workflowStepper.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const item=selected();if(!item)return;saveStep();const req=Number(b.dataset.step),allowed=Math.max(nextStep(item),activeStep);if(req>allowed&&item.status!=='live')return toast('Completa prima la fase precedente');activeStep=req;renderStep(item);el.workflowBody.scrollTop=0});el.workflowBackButton.onclick=()=>{if(activeStep>0){saveStep();activeStep--;renderStep(selected());el.workflowBody.scrollTop=0}};el.workflowNextButton.onclick=validateNext;el.workflowMoreButton.onclick=()=>openDialog(el.itemMenuDialog);document.getElementById('duplicateItemButton').onclick=()=>{const item=selected();if(!item)return;const copyItem=createInventoryItem({...item,id:undefined,code:undefined,status:'prep',sale:null,platforms:[],target:0,targetHistory:[],listing:{...normalizeListing(item.listing),platformStates:{},completedPlatforms:{},listingUrls:{},removalChecklist:[],photoCount:0,vintedResearchStarted:false,vintedVideoReady:false,vintedVideoName:'',vintedVideoSize:0,vintedVideoDuration:0,vintedVideoSelectedAt:'',vintedAnalysis:{},vintedSuggestedTarget:0,pricesConfirmed:false,publishedAt:''}},inventory);inventory.unshift(copyItem);saveInventory();closeDialog(el.itemMenuDialog);closeDialog(el.workflowDialog);renderWork();toast('Articolo duplicato senza foto');openWorkflow(copyItem.id,0)};document.getElementById('deleteItemButton').onclick=async()=>{const item=selected();if(!item||!confirm(`Eliminare definitivamente ${item.code}?`))return;await deleteItemPhotos(item.id).catch(()=>{});inventory=inventory.filter(i=>i.id!==item.id);saveInventory();closeDialog(el.itemMenuDialog);closeDialog(el.workflowDialog);renderCurrent();toast('Articolo eliminato')};document.getElementById('addPhotosButton').onclick=()=>el.workflowPhotoInput.click();el.workflowPhotoInput.onchange=async()=>{const item=selected();if(!item)return;try{await addItemPhotos(item.id,el.workflowPhotoInput.files,activePhotos.length,12);activePhotos=await getItemPhotos(item.id);item.listing={...normalizeListing(item.listing),photoCount:activePhotos.length};saveInventory();renderPhotos();renderWork();toast('Foto importate')}catch{toast('Impossibile importare le foto')}el.workflowPhotoInput.value=''};
document.getElementById('generateAiButton').onclick=generateAI;document.getElementById('importAiButton').onclick=importAI;document.getElementById('openAiSetupButton').onclick=openAiSetup;document.getElementById('copyAllListingButton').onclick=()=>{const item=selected();if(!item)return;collectListing(item);copy(`${titles(item).join('\n')}\n\n${item.listing.baseDescription}`,'Annuncio completo copiato')};document.getElementById('generateFallbackButton').onclick=()=>{const item=selected();if(!item)return;item.listing={...normalizeListing(item.listing),generatedTitles:generateTitleVariants(item),baseDescription:generateBaseDescription(item)};renderTitles(item);el.wfDescription.value=item.listing.baseDescription;saveInventory();toast('Testo generato dai dati presenti')};el.vintedVideoInput.onchange=()=>{const file=el.vintedVideoInput.files[0];if(file)selectResearchVideo(file);el.vintedVideoInput.value=''};document.getElementById('analyzeVintedVideoButton').onclick=analyzeResearchVideo;document.getElementById('importPriceAnalysisButton').onclick=importPriceAnalysis;document.getElementById('copyResearchPromptButton').onclick=copyResearchPrompt;document.getElementById('openChatGPTButton').onclick=openChatGPTForResearch;document.getElementById('openPriceAiSetupButton').onclick=openPriceAiSetup;document.getElementById('saveTargetButton').onclick=saveTarget;document.getElementById('editTargetButton').onclick=()=>{activeStep=2;renderStep(selected())};el.wfVestiaire.onchange=()=>{const item=selected();if(!item)return;item.listing={...normalizeListing(item.listing),vestiaireEnabled:el.wfVestiaire.checked};saveInventory();renderPlatforms(item)};el.completePublishingButton.onclick=completePublishing;
el.salePrice.oninput=()=>{if(['Vinted','Wallapop','Subito','Facebook Marketplace'].includes(el.salePlatform.value))el.saleNet.value=el.salePrice.value;salePreview()};el.saleNet.oninput=salePreview;el.saleCost.oninput=salePreview;el.salePlatform.onchange=()=>{if(['Vinted','Wallapop','Subito','Facebook Marketplace'].includes(el.salePlatform.value))el.saleNet.value=el.salePrice.value;salePreview()};el.saleForm.onsubmit=e=>{e.preventDefault();const item=selected(),p=parseMoney(el.salePrice.value),n=parseMoney(el.saleNet.value),cost=parseMoney(el.saleCost.value);if(!item||!p||n==null)return toast('Inserisci prezzo e incasso netto');const platform=el.salePlatform.value,l=normalizeListing(item.listing);if(cost!=null)item.cost=cost;item.sale={platform,price:p,net:n,date:el.saleDate.value||localDateISO(),currency:platform==='Grailed'?'USD':'EUR'};item.status='sold';item.platforms=[...new Set([...(item.platforms||[]),platform])];item.listing={...l,removalChecklist:createRemovalChecklist(item,platform)};item.updatedAt=new Date().toISOString();prefs.lastSalePlatform=platform;savePrefs();saveInventory();closeDialog(el.saleDialog);navigate('sold');copySale(item);openRemoval(item);toast('Vendita registrata e dati copiati')};document.getElementById('completeRemovalButton').onclick=()=>{const item=selected();if(!item)return;item.removedElsewhere=true;item.listing={...normalizeListing(item.listing),removalChecklist:(item.listing.removalChecklist||[]).map(e=>({...e,done:true}))};saveInventory();closeDialog(el.removalDialog);renderSold();toast('Rimozione completata')};
el.facebookEnabled.onchange=()=>{prefs.facebookEnabled=el.facebookEnabled.checked;savePrefs();renderCurrent()};el.ebayShipping.onchange=()=>{prefs.ebayShipping=Math.max(MIN_EBAY_SHIPPING,parseMoney(el.ebayShipping.value)||MIN_EBAY_SHIPPING);el.ebayShipping.value=fmt.x90.format(prefs.ebayShipping);savePrefs()};document.getElementById('openCalculatorButton').onclick=()=>{el.manualTarget.value='';manual();openDialog(el.calculatorDialog)};el.manualTarget.oninput=manual;document.getElementById('openAiSetupButtonData').onclick=openAiSetup;document.getElementById('openPriceAiSetupButtonData').onclick=openPriceAiSetup;document.getElementById('installButton').onclick=()=>openDialog(el.installDialog);document.getElementById('copyShortcutPromptButton').onclick=()=>copy(el.aiShortcutPrompt.value,'Prompt copiato');document.getElementById('openShortcutsButton').onclick=()=>location.href='shortcuts://';document.getElementById('saveAiSetupButton').onclick=()=>{localStorage.setItem(AI_SHORTCUT_CONFIG_KEY,el.aiConfiguredCheck.checked?'1':'0');closeDialog(el.aiSetupDialog);updateAi();toast('Configurazione salvata')};document.getElementById('copyPriceShortcutPromptButton').onclick=()=>copy(el.priceAiShortcutPrompt.value,'Prompt MXLAB Prezzo copiato');document.getElementById('openPriceShortcutsButton').onclick=()=>location.href='shortcuts://';document.getElementById('savePriceAiSetupButton').onclick=()=>{localStorage.setItem(PRICE_AI_SHORTCUT_CONFIG_KEY,el.priceAiConfiguredCheck.checked?'1':'0');closeDialog(el.priceAiSetupDialog);updatePriceAi();toast('MXLAB Prezzo configurato')};document.getElementById('exportBackupButton').onclick=exportBackup;document.getElementById('importBackupButton').onclick=()=>el.backupFileInput.click();el.backupFileInput.onchange=()=>{const f=el.backupFileInput.files[0];if(f)importBackup(f);el.backupFileInput.value=''};document.getElementById('exportCsvButton').onclick=()=>download(`mxlab-articoli-${localDateISO()}.csv`,inventoryToCsv(inventory),'text/csv;charset=utf-8');document.getElementById('clearDataButton').onclick=async()=>{if(!confirm('Cancellare tutti i dati locali MXLAB?'))return;localStorage.removeItem(INVENTORY_KEY);localStorage.removeItem(SALES_HISTORY_KEY);await clearAllPhotos().catch(()=>{});inventory=[];salesHistory=[];navigate('work');toast('Dati cancellati')};document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{if(d===el.workflowDialog){clearResearchVideoPreview();activeResearchVideo=null;activeResearchVideoItemId=null}if(![...document.querySelectorAll('dialog')].some(x=>x.open))document.body.classList.remove('dialog-open')}))}
function serviceWorker(){if(!('serviceWorker'in navigator))return;addEventListener('load',async()=>{try{const r=await navigator.serviceWorker.register('./sw.js?v=24',{updateViaCache:'none'});await r.update();let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload()})}catch{}})}
function init(){ensureMigration();applyTheme();el.appVersionLabel.textContent=`Hub v${APP_VERSION}`;el.workSort.value=prefs.workSort;el.workFilters.querySelectorAll('[data-work-filter]').forEach(b=>b.classList.toggle('active',b.dataset.workFilter===prefs.workFilter));document.getElementById('newPurchaseDate').value=localDateISO();el.aiShortcutPrompt.value=MXLAB_SHORTCUT_PROMPT;el.priceAiShortcutPrompt.value=MXLAB_PRICE_SHORTCUT_PROMPT;updateAi();updatePriceAi();events();navigate(prefs.view);serviceWorker();navigator.storage?.persist?.().catch(()=>false)}init();
